import React, { useState, useRef, useEffect, useCallback } from 'react';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import ProfModal from './ProfModal';

/* --- Sous-composants UI --- */
const Stars = ({ n }) => (
  <span style={{ color: '#f59e0b', fontSize: '0.8rem' }}>
    {"★".repeat(Math.round(n))}{"☆".repeat(5 - Math.round(n))} 
    <span style={{ color: 'var(--text2)', marginLeft: 5 }}>({n})</span>
  </span>
);

const ScoreBar = ({ score }) => (
  <div style={{ margin: '10px 0' }}>
    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.7rem', fontWeight: 700, marginBottom: 4 }}>
      <span>MATCHING SCORE</span>
      <span style={{ color: '#6c63ff' }}>{score}%</span>
    </div>
    <div style={{ height: 6, background: '#eee', borderRadius: 10, overflow: 'hidden' }}>
      <div style={{ height: '100%', width: `${score}%`, background: 'linear-gradient(90deg, #6c63ff, #ff6584)', transition: 'width 1s ease' }} />
    </div>
  </div>
);

function ProfChatCard({ prof, onViewProfile }) {
  return (
    <div style={{ background: '#fff', border: '1px solid #eee', borderRadius: 15, padding: 15, marginBottom: 15, boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
      <div style={{ display: 'flex', gap: 12, alignItems: 'center', marginBottom: 10 }}>
        <img src={prof.photo_url ? `http://localhost:8001${prof.photo_url}` : '/default-avatar.png'} alt="" 
             style={{ width: 45, height: 45, borderRadius: '50%', objectFit: 'cover', border: '2px solid #6c63ff' }} />
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 800, fontSize: '0.9rem' }}>{prof.nom}</div>
          <Stars n={prof.note_moyenne} />
        </div>
        <div style={{ textAlign: 'right', fontWeight: 800, color: '#43e97b' }}>{prof.tarif_en_ligne || prof.tarif_presentiel} DT/h</div>
      </div>

      <ScoreBar score={prof.score.total} />

      <p style={{ fontSize: '0.75rem', color: '#666', lineHeight: 1.4, margin: '10px 0' }}>{prof.bio.substring(0, 100)}...</p>

      <button onClick={() => onViewProfile(prof)} style={{ width: '100%', padding: '8px', background: '#f3f2ff', color: '#6c63ff', border: 'none', borderRadius: 8, fontWeight: 700, cursor: 'pointer' }}>
        Voir le profil complet
      </button>
    </div>
  );
}

/* --- Page Principale --- */
export default function Chatbot() {
  const { user } = useAuth();
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [top3, setTop3] = useState([]);
  const [selectedProf, setSelectedProf] = useState(null);
  const bottomRef = useRef(null);

  useEffect(() => bottomRef.current?.scrollIntoView({ behavior: 'smooth' }), [messages]);

  const onSend = async (text) => {
    const content = text || input;
    if (!content.trim()) return;

    const userMsg = { role: 'user', content, time: new Date().toLocaleTimeString() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      const res = await api.post('/api/chatbot/chat', { messages: [...messages, userMsg].map(m => ({ role: m.role, content: m.content })) });
      setMessages(prev => [...prev, { role: 'assistant', content: res.data.reply, time: new Date().toLocaleTimeString() }]);
      if (res.data.top3_profs) setTop3(res.data.top3_profs);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'assistant', content: "Erreur de connexion avec l'IA." }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ display: 'flex', height: 'calc(100vh - 70px)', background: '#f8f9fa' }}>
      {/* Zone Chat */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', borderRight: '1px solid #eee' }}>
        <div style={{ padding: 20, background: '#fff', borderBottom: '1px solid #eee', fontWeight: 800 }}>🤖 EduBot Assistant</div>
        <div style={{ flex: 1, overflowY: 'auto', padding: 20 }}>
          {messages.map((m, i) => (
            <div key={i} style={{ marginBottom: 20, textAlign: m.role === 'user' ? 'right' : 'left' }}>
              <div style={{ display: 'inline-block', padding: '12px 16px', borderRadius: 15, background: m.role === 'user' ? '#6c63ff' : '#fff', color: m.role === 'user' ? '#fff' : '#333', maxWidth: '80%', boxShadow: '0 2px 5px rgba(0,0,0,0.05)' }}>
                {m.content}
              </div>
            </div>
          ))}
          {loading && <div style={{ color: '#999', fontSize: '0.8rem' }}>EduBot réfléchit...</div>}
          <div ref={bottomRef} />
        </div>
        <div style={{ padding: 20, background: '#fff', display: 'flex', gap: 10 }}>
          <input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && onSend()} placeholder="Posez votre question ici..." style={{ flex: 1, padding: 12, border: '1px solid #eee', borderRadius: 10, outline: 'none' }} />
          <button onClick={() => onSend()} style={{ padding: '0 20px', background: '#6c63ff', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 700 }}>Envoyer</button>
        </div>
      </div>

      {/* Zone Recommandations */}
      <div style={{ width: 350, padding: 20, overflowY: 'auto' }}>
        <h3 style={{ fontSize: '1rem', fontWeight: 800, marginBottom: 20 }}>🏆 Suggestions pour vous</h3>
        {top3.length > 0 ? top3.map(p => (
          <ProfChatCard key={p.id} prof={p} onViewProfile={setSelectedProf} />
        )) : <div style={{ color: '#999', textAlign: 'center', marginTop: 50 }}>Parlez à EduBot pour voir des profs ici !</div>}
      </div>

      {selectedProf && <ProfModal prof={selectedProf} onClose={() => setSelectedProf(null)} />}
    </div>
  );
}
